import { useState } from "react";
import "./GameBoard.css";

const initialGameBoard = [
  [null, null, null],
  [null, null, null],
  [null, null, null],
];

export default function GameBoard() {
  const [GameBoard, setGameBoard] = useState(initialGameBoard);

  const HandelInputSymbol = (row, index) => {
    setGameBoard((prev) => {
      let UpdatedGameBoard = [...prev.map((innerArray) => [...innerArray])];
      UpdatedGameBoard[row][index] = "X";
      return UpdatedGameBoard;
    });
  };

  return (
    <>
      {GameBoard.map((row, index) => (
        <div key={index} className="rows">
          {row.map((symbol, index) => (
            <div key={index} className="blocks">
              <button onClick={() => HandelInputSymbol(row, index)}>
                {symbol}
              </button>
            </div>
          ))}
        </div>
      ))}
    </>
  );
}
